css:
.loader { --accent: var(--loader-color); --accent-2: var(--loader-secondary-color); width: var(--loader-size); height: calc(var(--loader-size) * .64); position: relative; }
.loader .sub { position: absolute; left: 18%; top: 38%; width: 62%; height: 30%; border-radius: 46% 50% 50% 46% / 50%; background: linear-gradient(var(--accent-2), var(--accent)); animation: sub-bob calc(var(--loader-speed) * 2.4) ease-in-out infinite; }
.loader .port { position: absolute; right: 16%; top: 28%; width: 16%; height: 42%; border-radius: 50%; background: color-mix(in srgb, #fff 55%, var(--accent-2)); box-shadow: inset 0 0 0 2px color-mix(in srgb, #000 25%, transparent); }
.loader .scope { position: absolute; left: 58%; bottom: 92%; width: 6%; height: 46%; border-radius: 3px; background: var(--accent); }
.loader .scope::after { content: ''; position: absolute; left: 60%; top: 0; width: 130%; height: 24%; border-radius: 2px; background: var(--accent); }
.loader .prop { position: absolute; left: -8%; top: 10%; width: 9%; height: 80%; border-radius: 50%; background: linear-gradient(#e2e8f0, #94a3b8); animation: sub-prop calc(var(--loader-speed) * .5) linear infinite; }
.loader i { position: absolute; width: 7%; height: 7%; border-radius: 50%; background: color-mix(in srgb, var(--accent-2) 80%, transparent); box-shadow: inset 0 0 0 1px var(--accent-2); opacity: 0; animation: sub-bubble calc(var(--loader-speed) * 2) ease-in infinite; }
.loader i:nth-of-type(1) { left: 26%; top: 34%; }
.loader i:nth-of-type(2) { left: 40%; top: 36%; animation-delay: calc(var(--loader-speed) * .66); }
.loader i:nth-of-type(3) { left: 54%; top: 32%; animation-delay: calc(var(--loader-speed) * 1.32); }
@keyframes sub-bob { 0%, 100% { transform: translateY(0) rotate(-2deg); } 50% { transform: translateY(-7%) rotate(2deg); } }
@keyframes sub-prop { 0%, 100% { transform: scaleY(1); } 50% { transform: scaleY(.18); } }
@keyframes sub-bubble { 0% { opacity: 0; transform: translateY(0) scale(.4); } 25% { opacity: .9; } 100% { opacity: 0; transform: translateY(-260%) scale(1.1); } }
